INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('人工智能工程师','信息技术 · 人工智能','["研发机器学习/深度学习模型，完成数据清洗、特征工程与模型训练调优", "将 AI 模型落地到业务场景（对话、视觉、推荐、预测）", "跟踪大模型/多模态前沿，做技术选型与模型评估部署"]','人工智能工程师是让机器具备感知、理解与决策能力的核心岗位，覆盖计算机视觉、自然语言处理、语音识别、推荐系统等方向，是大模型时代最紧缺的技术人才之一。','["扎实的数学基础（线代、概率论、最优化）", "熟练掌握 Python 与 PyTorch/TensorFlow 框架", "机器学习算法原理与模型调优经验", "大模型微调（Fine-tuning）与 RAG 工程实践"]','["英语文献阅读能力", "数据思维与业务理解", "团队协作与跨部门沟通", "持续学习能力（领域更新极快）"]','人才缺口长期居各行业前列，资深算法工程师年薪普遍 50 万以上；既懂 AI 又懂行业（医疗、金融、制造）的复合型人才最为稀缺。','算法工程师 → 高级算法工程师 → 算法专家/技术负责人 → 首席科学家；也可转向 AI 产品经理或创业。','大模型推动 AI 从演示走向生产，AI+行业应用、智能体（Agent）开发、模型部署与推理优化是未来五年热点。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('大数据工程师','信息技术 · 数据','["搭建和维护海量数据采集、清洗、存储与计算平台（Hadoop/Spark/Flink）", "建设数据仓库与数据指标体系，支撑业务分析", "保障数据质量、安全与实时计算链路稳定"]','大数据工程师负责企业数据基础设施的建设与运维，让 PB 级数据可存、可算、可用，是数据驱动决策的幕后架构师。','["Hadoop/Spark/Flink 等分布式计算框架", "SQL 与数据仓库建模（维度建模）", "Java/Scala/Python 至少一门熟练", "数据治理与数据质量体系建设"]','["业务抽象能力", "故障排查与运维意识", "跨团队沟通能力", "文档能力"]','所有中大型企业都需要数据底座，岗位需求稳定；实时计算与湖仓一体方向薪资上浮明显。','大数据开发 → 高级开发 → 数据架构师 → 首席数据官（CDO）方向。','湖仓一体、实时数仓、Data+AI（数据工程与 AI 工程融合）是明确趋势。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('云计算工程师','信息技术 · 云计算','["设计并维护企业云上架构（计算/存储/网络/安全）", "实现容器化部署与自动化运维（K8s/DevOps）", "优化云资源成本与系统高可用、容灾方案"]','云计算工程师负责企业在公有云/私有云上的系统架构与稳定运行，Kubernetes、微服务、Serverless 是日常工具栈。','["Linux 操作系统与网络基础", "Docker/Kubernetes 容器编排", "阿里云/腾讯云/AWS 至少一家熟练", "Terraform 等基础设施即代码（IaC）"]','["故障应急响应能力", "成本控制意识", "跨团队协作", "英文技术文档阅读"]','企业全面云化背景下需求持续增长，云原生方向人才供不应求；SRE/平台工程师薪资高于传统运维 50% 以上。','运维/开发工程师 → 云工程师 → 云架构师 → 技术总监。','云原生、边缘计算、AI 基础设施（GPU 集群调度）是未来重点。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('网络安全工程师','信息技术 · 安全','["开展渗透测试、漏洞扫描与安全评估", "设计企业安全防护体系（边界/主机/数据/应用）", "应急响应：处置入侵事件、溯源与修复加固"]','网络安全工程师守护企业数字资产，随着数据安全法、等保 2.0 落地，已从成本岗位变为合规刚需。','["网络协议与操作系统原理", "渗透测试与漏洞挖掘（CTF 经历加分）", "安全设备与 SIEM 平台使用", "等保测评与合规知识"]','["逻辑推理与逆向思维", "严谨细致", "应急处置能力", "持续跟进安全社区动态"]','人才缺口达百万级，政企、金融、能源行业需求最旺；资深安全专家年薪 60 万以上常见。','安全运维 → 渗透测试/安全研发 → 安全架构师 → CSO（首席安全官）。','数据安全、AI 安全（大模型攻防）、车联网/工控安全是新兴增长点。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('芯片设计工程师','信息技术 · 集成电路','["从事数字/模拟芯片前端设计或后端实现（布局布线）", "编写 RTL 代码并完成仿真验证、时序分析", "参与芯片架构定义与流片（Tape-out）全流程"]','芯片设计工程师是集成电路产业的核心研发岗位，国产替代浪潮下，数字 IC、模拟 IC、存储器、功率半导体各方向都在扩编。','["数字电路/模拟电路基础", "Verilog/SystemVerilog 与 EDA 工具（VCS/PrimeTime）", "计算机体系结构", "验证方法学（UVM）"]','["耐心与极致细致（流片一次成本极高）", "跨部门协作", "英文 datasheet 阅读", "文档与版本管理"]','行业处于黄金发展期，应届硕士起薪 30-50 万普遍，资深工程师年薪百万不罕见；但周期波动明显。','IC 设计工程师 → 资深工程师 → 技术专家/项目经理 → 架构师。','AI 芯片、车规芯片、RISC-V 生态是三大热点方向。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('机器人工程师','智能制造 · 机器人','["设计机器人运动控制、路径规划与感知算法", "完成机械臂/移动机器人集成调试与产线部署", "开发人机协作场景下的安全与交互方案"]','机器人工程师横跨机械、电子、控制与 AI，服务于工业自动化、服务机器人、人形机器人等快速增长的赛道。','["自动控制原理与运动学/动力学", "ROS 机器人操作系统", "C++/Python 与嵌入式开发", "机器视觉与传感器融合"]','["系统集成思维", "现场调试动手能力", "跨学科协作", "英语技术文献"]','人形机器人与具身智能成为投资风口，复合背景工程师极度稀缺，薪资逐年攀升。','研发工程师 → 系统工程师 → 技术负责人 → 产品线总经理。','具身智能、人形机器人量产、机器人+大模型（VLA 架构）是未来 5-10 年主线。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('新能源汽车工程师','智能制造 · 汽车','["负责三电系统（电池/电机/电控）或整车集成设计", "开展续航、热管理、充电性能测试与优化", "跟进智能驾驶（辅助驾驶）功能开发与标定"]','新能源汽车工程师身处全球最大新能源汽车市场，电动化与智能化双浪叠加，岗位涵盖电池、电驱、智驾、车联网等方向。','["电化学/电力电子/控制理论（按方向）", "CAN 总线与汽车电子架构", "AUTOSAR 或智驾算法基础", "仿真工具（MATLAB/Simulink）"]','["系统工程思维", "跨供应链协作", "安全意识", "快速迭代适应能力"]','中国新能源车产销量全球第一，人才持续紧缺；智能驾驶方向薪资对标互联网大厂。','工程师 → 主管工程师 → 系统经理 → 技术总监；智驾方向可转算法专家。','智能驾驶 L3 落地、800V 高压平台、固态电池、车路云一体化是热点。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('无人机飞手/工程师','智能制造 · 低空经济','["操控无人机完成航拍、测绘、巡检、植保等作业", "维护无人机设备，规划航线与处理飞行数据", "持照合规飞行，对接空域申请与安全规范"]','低空经济已上升为国家战略，无人机在电力巡检、农林植保、应急测绘、物流配送场景加速落地，飞手与运维工程师需求激增。','["无人机执照（CAAC 四类及以上）", "航拍摄影/测绘数据处理（Pix4D/大疆智图）", "设备维修与故障排查", "航线规划与气象判断"]','["空间判断力与手眼协调", "安全规范意识", "客户沟通能力", "户外作业适应能力"]','持证飞手缺口大，行业应用型飞手日薪可达千元以上；向飞行工程师、行业解决方案经理发展后收入翻倍。','飞手 → 资深飞手/教员 → 项目经理 → 行业解决方案负责人。','低空经济写入政府工作报告，物流无人机、eVTOL（电动垂直起降飞行器）是下一个爆发点。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('口腔医生','医疗健康 · 医师','["诊断与治疗龋病、牙周病、牙体牙髓疾病", "开展正畸、种植、修复等专科治疗", "口腔健康宣教与治疗方案设计"]','口腔医生是医疗行业中市场化程度最高的职业之一，兼具医疗技术与消费属性，私营口腔机构发展迅速。','["口腔解剖生理与病理学", "牙体牙髓/修复/正畸等临床技术", "口腔影像学判读", "无菌操作与院感规范"]','["精细操作与审美能力", "医患沟通", "经营意识（私立机构尤重）", "终身学习（新技术迭代快）"]','口腔医疗市场规模超千亿，种植与正畸集采后更加普惠化带动量增；成熟医生年收入 30-100 万以上。','住院医师规培 → 主治 → 副主任/主任医师；或加入连锁机构、自主开业。','数字化口腔（口扫、3D 打印、隐形正畸）重塑行业。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('康复治疗师','医疗健康 · 医技','["为术后、卒中、运动损伤患者制定康复训练方案", "实施物理治疗、作业治疗与言语治疗", "评估康复效果并调整疗程"]','康复治疗师帮助患者恢复功能、回归生活，老龄化与运动损伤增多推动需求持续上升，是医疗体系中的紧缺岗位。','["康复评定学（肌力/关节活动度/平衡）", "物理治疗技术（PT/OT/ST）", "解剖学与运动生理学", "康复设备使用"]','["耐心与共情", "沟通能力", "体力与手法技巧", "团队协作（医护康一体）"]','全国康复治疗师缺口数十万人，运动康复、儿童康复、产后康复细分方向发展快；资深治疗师可自主创业工作室。','治疗师 → 主管治疗师 → 治疗师长 → 康复科主任/工作室主理人。','康复医疗纳入医保范围扩大，银发经济带动社区与居家康复。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('健康管理师','医疗健康 · 健康服务','["采集分析个人健康信息，建立健康档案", "制定个性化健康管理方案（饮食/运动/作息）", "开展健康风险评估、随访与健康教育"]','健康管理师从治已病走向治未病，服务高净值人群、企业客户与社区慢病管理，是大健康产业的连接型岗位。','["基础医学与营养学知识", "健康风险评估工具使用", "慢病管理流程", "健康数据分析"]','["沟通与亲和力", "方案设计能力", "客户维护", "跨机构资源链接"]','大健康产业规模迈向万亿级，体检机构、保险公司、康养社区、互联网健康平台均在布局；高端私人健康管理师按年收费。','健康管理师 → 资深顾问 → 健康管理中心负责人 → 私人健康管家/创业。','AI+健康管理（可穿戴设备数据接入）让服务个性化、规模化。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('全媒体运营师','现代服务 · 新媒体','["策划并运营公众号、视频号、抖音、小红书等全平台内容", "分析数据（播放/转化/涨粉）并迭代运营策略", "统筹选题、拍摄、剪辑与投放全流程"]','全媒体运营师是 2020 年人社部认证的新职业，负责企业在新媒体阵地的品牌传播与获客转化，是数字化营销的核心岗位。','["内容策划与文案能力", "短视频脚本/拍摄/剪辑（剪映/PR）", "平台算法与投放（DOU+/千川）", "数据分析（新榜/蝉妈妈等）"]','["网感与热点敏感度", "审美能力", "项目统筹", "复盘思维"]','几乎所有行业都需要新媒体获客，优质操盘手供不应求；带货主播与运营合伙人模式让头部从业者收入上不封顶。','运营专员 → 资深运营/操盘手 → 运营总监 → 合伙人/自媒体创业。','AI 生成内容（AIGC）辅助量产、直播电商精细化、私域运营是方向。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('电商运营','现代服务 · 电商','["负责店铺（天猫/京东/拼多多/抖音小店）日常运营与活动策划", "优化商品链接（标题/主图/详情）提升搜索与转化", "投放直通车/引力魔方等付费流量并控制 ROI"]','电商运营掌管线上店铺的生意全局，从选品、流量、转化到复购，直接对销售额负责，是品牌电商化的核心操盘手。','["平台规则与搜索逻辑", "数据分析（生意参谋等）", "付费投放与 ROI 控制", "活动策划（大促节奏）"]','["商业敏感度", "抗压能力", "跨团队协调（设计/客服/供应链）", "快速试错迭代"]','直播电商与兴趣电商持续扩容，懂内容+懂投放的复合型运营最抢手；资深运营年薪 30-60 万，合伙人分红上不封顶。','运营助理 → 店长/运营经理 → 电商总监 → 品牌合伙人。','全域电商（货架+内容）、AI 客服与 AI 素材生成、跨境电商是增长点。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('跨境电商运营','现代服务 · 跨境电商','["运营 Amazon/Shopee/TikTok Shop/Temu 等海外店铺", "选品分析、Listing 优化与海外广告投放", "处理跨境物流、支付、合规与售后"]','跨境电商让中国商品直连全球消费者，TikTok Shop 与 Temu 带动新一轮出海浪潮，运营人才缺口持续扩大。','["电商平台规则与广告投放", "英语或小语种读写", "选品与市场分析工具", "跨境物流与关务基础"]','["跨文化沟通", "数据敏感度", "合规意识", "熬夜应对时差能力"]','跨境电商进出口规模持续增长，资深运营与操盘手稀缺；成功店铺合伙人年收入百万级案例常见。','运营 → 主管 → 操盘手/总监 → 自建品牌出海。','TikTok 内容电商、半托管模式、品牌出海（DTC 独立站）是主线。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('家庭教育指导师','现代服务 · 教育服务','["为家长提供亲子沟通、学习习惯培养指导", "制定个性化家庭教育方案并跟踪落地", "开展家庭教育讲座与个案咨询"]','家庭教育指导师伴随《家庭教育促进法》实施成为新兴职业，帮助家庭改善亲子关系与养育方式，与教培转型方向高度契合。','["儿童发展心理学", "家庭教育理论与咨询技术", "个案评估与方案设计", "讲座与工作坊带领"]','["倾听与共情", "边界感与职业道德", "表达能力", "案例复盘能力"]','政策加持下学校、社区、机构普遍设置家庭教育指导岗位；成熟咨询师按小时收费 300-1000 元，私教需求旺盛。','指导师 → 资深咨询师 → 机构督导/培训讲师 → 个人工作室。','与心理咨询、生涯规划融合，家庭教育+学习力复合服务是溢价点。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('生涯规划师','现代服务 · 教育服务','["通过测评与访谈了解学生的兴趣、能力与价值观", "制定选科、升学路径与职业规划方案", "跟踪执行效果并动态调整规划"]','生涯规划师帮助学生与家长做出升学与职业选择，新高考改革与就业不确定性让专业规划服务从锦上添花变成刚需。','["生涯测评工具（霍兰德/MBTI 等）解读", "新高考政策与升学路径（强基/综评/专项）", "咨询对话技术", "院校专业数据库运用"]','["同理心与沟通", "信息整合能力", "报告撰写", "职业伦理（不承诺、不夸大）"]','新高考省份全覆盖带动市场爆发，单次规划服务收费千元至万元；与学科提分结合的规划+伴学模式客单价最高。','规划师 → 资深规划师 → 校区总监/教研负责人 → 个人 IP 工作室。','AI 测评+人工解读、低龄段（初中）规划前置、多元升学（港澳/中外合作）咨询增长。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('金融分析师','金融财会 · 投资研究','["研究宏观、行业与上市公司，撰写研究报告", "搭建财务模型，给出投资评级与目标价", "为基金/券商/企业的投资决策提供支持"]','金融分析师在券商研究所、公募基金、资管机构从事投资研究工作，是金融行业的智库岗位，应届生起薪行业顶尖。','["财务分析与估值建模（DCF/可比公司）", "行业研究框架与数据处理（Wind/Bloomberg）", "宏观经济与政策分析", "报告撰写与路演表达"]','["逻辑思维", "抗压与勤奋", "沟通路演能力", "合规意识"]','头部机构应届起薪 30-60 万，资深分析师年薪百万以上；向基金经理、投资总监发展空间大，但竞争激烈。','研究员助理 → 分析师 → 资深分析师/首席 → 基金经理/投资总监。','量化与 AI 投研工具普及，基本面+量化复合背景更吃香。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('精算师','金融财会 · 保险精算','["建立保险产品的费率与准备金模型", "评估偿付能力风险与资产负债匹配", "参与新产品定价与经验分析"]','精算师是保险与金融行业的定价大脑，持证门槛高、培养周期长，历来是金融业黄金职业之一。','["概率论与数理统计", "精算模型（寿险/非寿险）", "金融数学与编程（R/Python）", "中国/北美精算考试体系"]','["严谨细致", "长期学习能力", "商业理解", "沟通（向非精算人员解释结论）"]','持证精算师全国仅数千人，供需失衡；保险公司、咨询公司、监管科技均需精算人才，资深精算师年薪 80-200 万。','精算分析师 → 精算经理 → 总精算师（保险公司高管序列）。','IFRS17 会计准则落地、健康险创新、大数据定价带来新需求。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('注册会计师','金融财会 · 审计','["审计企业财务报表并出具审计意见", "税务筹划与内控咨询", "企业 IPO、并购重组中的财务尽调"]','注册会计师（CPA）是国内财经领域含金量最高的执业资格之一，执业于会计师事务所或企业财务高管岗位。','["会计审计准则与税法", "财务报表分析", "Excel/审计软件（鼎信诺等）", "CPA 六科知识体系"]','["严谨与职业怀疑", "抗压（年审季加班）", "沟通函证能力", "持续学习（准则更新）"]','四大与本土八大事务所需求稳定，CPA+经验是财务总监硬通货；执业注会签字权稀缺，全职收入可观。','审计助理 → 项目经理 → 合伙人；或转企业财务经理 → 财务总监（CFO）。','业财融合、财务数字化（ERP/BI）、ESG 报告审计是新增长点。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('军队文职人员','法律政务 · 国防','["在军队院校、医院、科研机构从事专业技术或管理工作", "执行军队条令条例，参与战备值班与训练", "按军队编制享受相应职级待遇"]','军队文职是军队人员的组成部分，面向社会公开招聘，岗位涵盖医疗、工程、教学、管理等，近年报考热度持续走高。','["岗位对应专业能力（医疗/工程/会计等）", "军队文职招考笔试（公共科目+专业）", "公文写作与办公软件", "政治素养与纪律意识"]','["稳定性适应", "服从意识", "团队协作", "身心素质"]','待遇参照现役军官标准（六险二金、住房医疗优厚），编制稳定竞争小于公务员；适合追求稳定的毕业生。','技术/管理岗位逐级晋升，走军队职级序列。','招考规模逐年扩大，理工类与医疗类岗位占比最高。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('选调生','法律政务 · 公务员','["作为党政领导干部后备人选在基层锻炼", "从事乡镇街道综合管理、乡村振兴等工作", "服务期满后择优选拔进入县级以上机关"]','选调生是公务员中的快车道，面向优秀应届毕业生定向招录，组织部门跟踪培养，晋升速度普遍快于普通公务员。','["公共基础知识与申论写作", "政策理解与文字功底", "群众工作与矛盾调解", "办公软件与数据报表"]','["政治素养", "吃苦耐劳（基层锻炼 2 年起）", "沟通协调", "廉洁自律"]','职业稳定性极强，晋升通道明确；定向选调生起点高（硕士定四级主任科员），是名校文科生的热门选择。','选调生 → 副科/正科（基层历练）→ 处级及以上；也可遴选进入省市机关。','中央与各省定向选调向紧缺专业（计算机、经济、法律）倾斜。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('游戏设计师','文化传媒 · 游戏','["设计游戏玩法、关卡与数值体系", "撰写世界观、剧情与角色设定", "协调美术、程序推进版本迭代，分析玩家数据"]','游戏设计师是从玩游戏到做游戏的创造者，中国游戏市场规模全球第一，精品化与出海浪潮扩大了对优秀设计人才的需求。','["游戏机制与数值设计", "剧情写作与关卡设计", "引擎工具（Unity/UE 基础）", "玩家心理与数据分析"]','["创意与表达能力", "团队协作（美术/程序/策划三角）", "热爱与玩家同理心", "抗压（版本节点）"]','头部厂商策划起薪 20-40 万，主策划/制作人年薪百万级；小程序游戏与独立游戏给了新人更多机会。','策划助理 → 系统/数值/文案策划 → 主策划 → 制作人。','AI 辅助美术与剧情生成、小游戏（微信/抖音）爆发、文化出海是增长点。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('短视频编导','文化传媒 · 影视','["策划短视频选题、脚本与分镜", "现场执导拍摄，把控节奏与呈现", "复盘数据并迭代内容模型（人设/结构/钩子）"]','短视频编导是内容产业的新工种，决定一条视频的爆款概率，服务达人、品牌与 MCN 机构，作品即简历。','["叙事结构与钩子设计", "脚本与分镜写作", "拍摄剪辑基础（能独立出片）", "平台内容生态理解"]','["网感与热点判断", "沟通协调（拍摄团队）", "数据复盘", "抗压与高频产出"]','优秀编导按账号分成或底薪+提成，头部 MCN 编导月薪 2-5 万起；积累账号案例后可自主创业。','编导助理 → 编导 → 内容总监/账号主理人 → MCN 合伙人。','AI 剪辑与数字人降低制作成本，剧情化+知识类内容持续走强。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('城市规划师','建筑工程 · 城乡规划','["编制城市总体规划、控制性详细规划", "参与城市更新、片区策划与交通市政专项", "绘制规划图纸并撰写技术文件，对接自然资源部门审批"]','城市规划师决定城市空间的生长逻辑，城市更新时代从增量扩张转向存量提质，对懂设计、懂政策、懂数据的复合规划师需求上升。','["城乡规划原理与设计（CAD/GIS/PS/SU）", "国土空间规划政策体系", "城市经济与数据分析", "规划文本与图则编制"]','["空间审美", "公文与技术写作能力", "多方协调（政府/开发商/公众）", "政策敏感度"]','设计院校规划专业入职设计院或规划院，注册城乡规划师持证后薪资显著提升；城市更新、乡村振兴咨询是新蓝海。','助理规划师 → 规划师 → 主任规划师/项目负责人 → 总规划师。','城市更新、完整社区、TOD 综合开发、数字化（CIM 平台）规划。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('轨道交通工程师','交通物流 · 轨道交通','["参与地铁/高铁线路、车站的勘察设计与施工管理", "负责信号、供电、车辆等机电系统的安装调试", "运营阶段做设备维护、故障诊断与安全保障"]','轨道交通工程师服务国家大规模基建与城市轨道网络，覆盖设计、施工、运营全生命周期，项目制培养体系成熟。','["土木工程/电气/信号专业知识", "CAD 与工程建模", "施工组织与安全管理", "相关注册执业资格（建造师等）"]','["现场适应能力", "责任心（安全攸关）", "多方协调", "工程文档"]','城市轨道交通里程持续增长，运营维保人才缺口大；海外基建项目（一带一路）提供外派高薪机会。','技术员 → 工程师 → 项目总工/部门经理 → 总工程师。','智能运维、全自动运行（UTO）线路、既有线改造。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('储能工程师','能源环保 · 新能源','["设计储能电站系统方案（电化学/机械储能）", "开展电池管理系统（BMS）与能量管理系统（EMS）调试", "负责并网测试、安全评估与运维优化"]','储能工程师是双碳目标下的明星职业，新能源发电占比提升倒逼储能爆发，锂电池、钠电池、液流电池路线并行发展。','["电化学与电力电子基础", "BMS/EMS 系统架构", "电气设计与并网规范", "热管理与安全设计"]','["系统工程思维", "安全意识", "项目现场适应", "跨专业协作"]','行业处于产能扩张期，电芯、PCS、系统集成各环节均缺人；资深储能系统工程师年薪 40-80 万。','研发/应用工程师 → 系统工程师 → 技术总监；或转项目管理/产品经理。','大容量长时储能、构网型储能、光储充一体化。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('碳排放管理员','能源环保 · 双碳','["盘查企业碳排放数据，编制碳排放报告", "参与碳交易配额管理与履约", "制定企业降碳路径（节能/绿电/碳汇）"]','碳排放管理员是 2021 年列入国家职业分类的新职业，伴随全国碳市场上线，企业履约与 ESG 披露需求催生大量岗位。','["温室气体核算标准（ISO14064 等）", "碳市场规则与 MRV 体系", "能源审计与数据分析", "ESG 报告框架"]','["政策敏感度", "数据严谨性", "咨询沟通能力", "学习能力（规则快速演进）"]','纳入碳市场行业逐年扩容，控排企业、咨询机构、交易所均需专业人才；资深碳资产管理人年薪 30-60 万。','碳排放管理员 → 碳资产经理 → ESG/可持续发展负责人。','CCER 重启、产品碳足迹、ESG 强制披露（上市公司）。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('智慧农业工程师','农林牧渔 · 现代农业','["设计农业物联网方案（传感器/水肥一体化/无人机巡田）", "建设农业大数据平台，输出种植决策模型", "培训农户与农企使用智能装备"]','智慧农业工程师用技术赋能传统农业，无人农场、植物工厂、精准畜牧是落地场景，乡村振兴与粮食安全战略提供长期政策红利。','["农业物联网与传感技术", "数据分析与种植模型", "无人机与智能农机应用", "农业气象与土壤学基础"]','["下沉市场沟通", "动手实践", "成本意识", "对农业的热情"]','农业数字化渗透率极低、天花板高，政府项目与企业投资双轮驱动；兼具农业+IT 背景的人才极度稀缺。','实施工程师 → 方案经理 → 农业数字化负责人/创业（农业科技公司）。','AI 大田决策、农业机器人、垂直农业与城市农场。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
